from unittest.mock import patch
from _pytest.compat import num_mock_patch_args, getfuncargnames

class AmbiguousNew:
    def __eq__(self, other):
        raise ValueError("ambiguous truth value")

@patch('anything', new=AmbiguousNew())
def f():
    pass

print(num_mock_patch_args(f))
assert num_mock_patch_args(f) == 0

# Also verify a normal patch with DEFAULT still consumes the injected mock arg
@patch('anything')
def g(mock_arg):
    pass

print(num_mock_patch_args(g))
assert num_mock_patch_args(g) == 1
assert getfuncargnames(g) == ()
print('all assertions passed')
PY
